{
  "passageId": "audio-perceptual-coding",
  "items": [
    {
      "slot": 1,
      "stem": "윗글의 내용과 일치하지 않는 것으로 적절하지 않은 것은?",
      "stemPolarity": "SELECT_INCORRECT",
      "choices": [
        {
          "number": 1,
          "text": "축음기는 소리에 따른 나팔의 진동을 바늘이 판에 홈으로 새기도록 하여 소리를 저장한다."
        },
        {
          "number": 2,
          "text": "디지털 오디오 신호에서 각 소리 크기에 할당되는 비트 수가 늘어나면 소리는 아날로그 원음에 가까워진다."
        },
        {
          "number": 3,
          "text": "100 Hz 이하의 소리는 1,000 Hz부터 10,000 Hz 사이의 소리보다 훨씬 커야 청각으로 감지할 수 있다."
        },
        {
          "number": 4,
          "text": "큰 소리와 작은 소리의 주파수가 서로 가까울수록 두 소리 사이에서는 차폐가 일어나기 어렵다."
        },
        {
          "number": 5,
          "text": "지각부호화에서는 오디오 신호를 압축하기 위해 먼저 주파수에 따라 여러 개의 임계대역으로 나눈다."
        }
      ],
      "answer": 4
    },
    {
      "slot": 2,
      "stem": "윗글의 내용에 대한 이해로 적절한 것은?",
      "stemPolarity": "SELECT_CORRECT",
      "choices": [
        {
          "number": 1,
          "text": "초기 녹음기는 소리를 아날로그 형태로 저장했지만 그 바로 다음에 등장한 매체부터는 디지털 형태로 기록하였다."
        },
        {
          "number": 2,
          "text": "일반적인 16비트 오디오 파일에서는 소리 크기에 따라 할당되는 이진수의 자릿수를 달리하여 소리를 구별한다."
        },
        {
          "number": 3,
          "text": "지각부호화는 최소가청강도와 차폐라는 청각 특성을 이용하여 감도가 낮은 소리를 제거함으로써 오디오 신호를 압축한다."
        },
        {
          "number": 4,
          "text": "임계대역의 폭은 차폐음의 주파수에 따라 달라지며 고음의 임계대역은 저음의 임계대역보다 훨씬 좁다."
        },
        {
          "number": 5,
          "text": "오디오 파일은 데이터 양이 많더라도 저장 공간을 절약하기 위해 오디오 신호를 압축할 필요는 없다."
        }
      ],
      "answer": 3
    },
    {
      "slot": 3,
      "stem": "차폐 문턱값에 대한 이해로 적절한 것은?",
      "stemPolarity": "SELECT_CORRECT",
      "choices": [
        {
          "number": 1,
          "text": "차폐 문턱값은 최소가청강도와 동일한 기준으로서 차폐 여부를 구별하지 않고 청각의 최소 감지 크기를 나타낸다."
        },
        {
          "number": 2,
          "text": "지각부호화에서는 각 임계대역의 최소가청강도와 차폐음을 고려하여 차폐 문턱값을 구한다."
        },
        {
          "number": 3,
          "text": "지각부호화에서는 차폐 문턱값을 넘는 소리의 크기와 문턱값의 차이가 클수록 해당 소리에 비트를 적게 할당한다."
        },
        {
          "number": 4,
          "text": "지각부호화에서는 차폐 문턱값보다 작은 소리가 들리지 않는다고 판단하면서도 이를 제거하지 않고 남겨 둔다."
        },
        {
          "number": 5,
          "text": "차폐 문턱값은 차폐를 고려할 때 실제 청각이 감지할 수 있는 소리 주파수의 최솟값을 나타낸다."
        }
      ],
      "answer": 2
    }
  ]
}

